def initialize_mass_balance_projector(self, data_or_matrix) -> None:
    """Lazily initialize the mass balance projector.

    Accepts either a ``Data`` object with ``incidence_matrix`` attribute,
    or a raw stoichiometric matrix tensor.
    """
    if self.mass_balance_projector is not None:
        return

    if isinstance(data_or_matrix, torch.Tensor):
        matrix = data_or_matrix
    elif hasattr(data_or_matrix, "incidence_matrix"):
        matrix = data_or_matrix.incidence_matrix
    elif hasattr(data_or_matrix, "dataset") and hasattr(data_or_matrix.dataset, "incidence_matrix"):
        matrix = data_or_matrix.dataset.incidence_matrix
    else:
        return

    self.mass_balance_projector = MassBalanceProjector(
        stoichiometric_matrix=matrix,
        max_regularization=self.config.mass_balance_max_reg,
    )

def _create_cross_modal_mask(self, edge_index, metabolite_indices,
                              reaction_indices, device):
    """Create boolean mask ``[1, M, R]`` for cross-modal attention."""
    num_m = len(metabolite_indices)
    num_r = len(reaction_indices)
    mask = torch.zeros(1, num_m, num_r, dtype=torch.bool, device=device)

    if self.neighbor_cache is not None:
        # Build global->local reaction index map
        max_idx = reaction_indices.max().item()
        rxn_g2l = torch.full((max_idx + 1,), -1, device=device, dtype=torch.long)
        rxn_g2l[reaction_indices] = torch.arange(num_r, device=device)

        met_cpu = metabolite_indices.cpu().numpy()
        for local_m, global_m in enumerate(met_cpu):
            global_m = int(global_m)
            if global_m in self.neighbor_cache:
                nbrs = self.neighbor_cache[global_m]
                if len(nbrs) > 0:
                    local_nbrs = rxn_g2l[nbrs]
                    valid = local_nbrs >= 0
                    mask[:, local_m, local_nbrs[valid]] = True
    else:
        # Fallback: build mask from edge_index
        src, dst = edge_index
        met_set = set(metabolite_indices.cpu().numpy().tolist())
        rxn_set = set(reaction_indices.cpu().numpy().tolist())

        met_g2l = {int(v): i for i, v in enumerate(metabolite_indices.cpu().numpy())}
        rxn_g2l_dict = {int(v): i for i, v in enumerate(reaction_indices.cpu().numpy())}

        for i in range(src.size(0)):
            s, d = int(src[i]), int(dst[i])
            if s in met_set and d in rxn_set:
                mask[0, met_g2l[s], rxn_g2l_dict[d]] = True
            elif s in rxn_set and d in met_set:
                mask[0, met_g2l[d], rxn_g2l_dict[s]] = True

    return mask

def standardize_batch_data(data: Data) -> Data:
    """Standardize a PyG Data object to always have batch dimensions.

    Ensures all node features have shape ``[batch_size, num_nodes, feature_dim]``
    and all targets / masks have shape ``[batch_size, num_nodes]``.
    """
    if not hasattr(data, "batch_size"):
        data.batch_size = 1

        if hasattr(data, "x_embedding") and data.x_embedding is not None and data.x_embedding.dim() == 2:
            data.x_embedding = data.x_embedding.unsqueeze(0)
        if hasattr(data, "x_gene") and data.x_gene is not None and data.x_gene.dim() == 2:
            data.x_gene = data.x_gene.unsqueeze(0)
        if hasattr(data, "x_smiles") and data.x_smiles is not None and data.x_smiles.dim() == 2:
            data.x_smiles = data.x_smiles.unsqueeze(0)
        if hasattr(data, "x") and data.x is not None and data.x.dim() == 2:
            data.x = data.x.unsqueeze(0)
        if hasattr(data, "y") and data.y is not None and data.y.dim() == 1:
            data.y = data.y.unsqueeze(0)
        if hasattr(data, "mask") and data.mask is not None and data.mask.dim() == 1:
            data.mask = data.mask.unsqueeze(0)

    validate_batch_shapes(data)
    return data

def validate_batch_shapes(data: Data) -> None:
    """Validate that all tensors have consistent batch dimensions."""
    if not hasattr(data, "batch_size"):
        return
    batch_size = data.batch_size

    for attr in ("x_embedding", "x_gene", "x_smiles"):
        t = getattr(data, attr, None)
        if t is not None:
            assert t.dim() == 3, f"{attr} should be 3D, got {t.dim()}D"
            assert t.size(0) == batch_size, f"{attr} batch size mismatch: {t.size(0)} != {batch_size}"

    if hasattr(data, "y") and data.y is not None:
        assert data.y.dim() == 2, f"y should be 2D, got {data.y.dim()}D"
        assert data.y.size(0) == batch_size, f"y batch size mismatch"

    if hasattr(data, "mask") and data.mask is not None:
        assert data.mask.dim() == 2, f"mask should be 2D, got {data.mask.dim()}D"
        assert data.mask.size(0) == batch_size, f"mask batch size mismatch"

def get_batch_size(data: Data) -> int:
    """Return batch size from a Data object (defaults to 1)."""
    return getattr(data, "batch_size", 1)

def create_default_features(num_nodes: int, feature_dim: int,
                            batch_size: int, device: torch.device) -> torch.Tensor:
    """Create zero features with proper batch dimension ``[B, N, D]``."""
    return torch.zeros(batch_size, num_nodes, feature_dim, device=device)

def expand_to_batch(tensor: torch.Tensor, batch_size: int) -> torch.Tensor:
    """Expand a tensor to match *batch_size*.

    Handles ``[N, D] -> [B, N, D]`` and ``[N] -> [B, N]``.
    """
    if tensor is None:
        return tensor
    if tensor.dim() == 1:
        return tensor.unsqueeze(0).expand(batch_size, -1)
    elif tensor.dim() == 2:
        return tensor.unsqueeze(0).expand(batch_size, -1, -1)
    elif tensor.dim() == 3 and tensor.size(0) == 1:
        return tensor.expand(batch_size, -1, -1)
    elif tensor.dim() == 3 and tensor.size(0) == batch_size:
        return tensor
    else:
        raise ValueError(f"Cannot expand tensor of shape {tensor.shape} to batch_size={batch_size}")

def _init_weights(self):
    for mod in [self.query_projection, self.key_projection, self.value_projection]:
        nn.init.xavier_uniform_(mod.weight)
        nn.init.zeros_(mod.bias)
    for mod in self.smiles_projection:
        if isinstance(mod, nn.Linear):
            nn.init.xavier_uniform_(mod.weight)
            nn.init.zeros_(mod.bias)
    for mod in self.prediction_mlp:
        if isinstance(mod, nn.Linear):
            nn.init.xavier_uniform_(mod.weight)
            nn.init.zeros_(mod.bias)
    if self.use_gene_skip:
        for mod in self.gene_projection:
            if isinstance(mod, nn.Linear):
                nn.init.xavier_uniform_(mod.weight)
                nn.init.zeros_(mod.bias)

def _assert_finite(x: torch.Tensor, name: str) -> None:
    if not torch.isfinite(x).all():
        raise RuntimeError(f"{name} has NaN/Inf")

def _reshape_for_attention(self, x):
    """``[B, S, D] -> [B, H, S, D_h]``"""
    B, S, _ = x.shape
    return x.view(B, S, self.num_heads, self.head_dim).transpose(1, 2)

def _reshape_from_attention(self, x):
    """``[B, H, S, D_h] -> [B, S, D]``"""
    B, _, S, _ = x.shape
    return x.transpose(1, 2).contiguous().view(B, S, self.hidden_dim)

def _cross_attention(self, q, k, v, mask=None):
    scores = torch.matmul(q, k.transpose(-2, -1)) / (self.scale * self.temperature)
    if mask is not None:
        scores = scores.masked_fill(mask == 0, -1e9)
    weights = F.softmax(scores, dim=-1)
    weights = self.dropout(weights)
    return torch.matmul(weights, v)

def _validate_and_refresh_cache(self, S):
    needs = (
        self.L is None
        or self.cached_device != S.device
        or self.cached_dtype != S.dtype
        or self.num_metabolites != S.size(0)
        or self.num_reactions != S.size(1)
    )
    if needs:
        self._precompute_cholesky_factor(S)

def _project_pseudoinverse_fallback(self, y, S_dense):
    try:
        SST = torch.mm(S_dense, S_dense.T)
        reg = 1e-6 * torch.eye(SST.size(0), device=SST.device, dtype=SST.dtype)
        SST_pinv = torch.pinverse(SST + reg)

        projected = []
        for b in range(y.size(0)):
            r_b = torch.mv(S_dense, y[b])
            w_b = torch.mv(SST_pinv, r_b)
            correction_b = torch.mv(S_dense.T, w_b)
            projected.append(y[b] - correction_b)
        return torch.stack(projected, dim=0)
    except Exception:
        warnings.warn("Pseudo-inverse fallback also failed. Returning original fluxes.")
        return y

def forward(self, y, S):
    """Forward pass for ``nn.Module`` compatibility."""
    return self.project_to_mass_balance(y, S)

