def install_deps():
    """Install Python dependencies if missing."""
    req_path = os.path.join(PROJECT_ROOT, "requirements.txt")
    if not os.path.exists(req_path):
        return

    # Quick check: try importing the heaviest optional dep
    try:
        import datasets  # noqa: F401
        return  # already installed
    except ImportError:
        pass

    print("Installing dependencies...")
    # Prefer uv (available on Vast.ai template) for speed, fall back to pip
    uv = subprocess.run(["which", "uv"], capture_output=True)
    if uv.returncode == 0:
        cmd = ["uv", "pip", "install", "-r", req_path]
    else:
        cmd = [sys.executable, "-m", "pip", "install", "-r", req_path]

    subprocess.run(cmd, check=True)
    print()

def find_checkpoint():
    """Find the best available checkpoint."""
    ckpt_dir = os.path.join(os.path.dirname(__file__), "..", "checkpoints")
    final = os.path.join(ckpt_dir, "final_model.pt")
    if os.path.exists(final):
        return final
    # Fall back to latest checkpoint
    if os.path.isdir(ckpt_dir):
        pts = sorted([f for f in os.listdir(ckpt_dir) if f.endswith(".pt")])
        if pts:
            return os.path.join(ckpt_dir, pts[-1])
    return None

def count_fixed_positions(grid):
    """Count non-MASK positions in a grid."""
    return (grid != MASK_TOKEN).sum().item()

class ASCIIDataset(Dataset):
    def __init__(self, data_tensor):
        """
        Args:
            data_tensor: [N, H, W] long tensor of character indices
        """
        self.data = data_tensor

    def __len__(self):
        return len(self.data)

    def __getitem__(self, idx):
        grid = self.data[idx]  # [H, W]
        masked_grid, target_grid, mask = random_mask(grid)
        return masked_grid, target_grid, mask

def get_cosine_schedule_with_warmup(optimizer, warmup_steps, total_steps):
    """Linear warmup followed by cosine decay to 0."""
    def lr_lambda(step):
        if step < warmup_steps:
            return step / max(1, warmup_steps)
        progress = (step - warmup_steps) / max(1, total_steps - warmup_steps)
        return max(0.0, 0.5 * (1.0 + math.cos(math.pi * progress)))
    return LambdaLR(optimizer, lr_lambda)

def set_seed(seed=42):
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    if torch.cuda.is_available():
        torch.cuda.manual_seed_all(seed)

