def _find_mono_font(size=32):
    """Find a monospace font, falling back to PIL default."""
    candidates = [
        "/usr/share/fonts/truetype/dejavu/DejaVuSansMono.ttf",
        "/usr/share/fonts/TTF/DejaVuSansMono.ttf",
        "/usr/share/fonts/truetype/liberation/LiberationMono-Regular.ttf",
        "/System/Library/Fonts/Menlo.ttc",
        "/System/Library/Fonts/Monaco.ttf",
    ]
    for path in candidates:
        if os.path.exists(path):
            return ImageFont.truetype(path, size), path
    return ImageFont.load_default(), "PIL default"

def _pil_to_tensor(pil_img):
    """Convert a PIL image to a [3, H, W] float tensor in [0, 1]."""
    if pil_img.mode != "RGB":
        pil_img = pil_img.convert("RGB")
    return T.ToTensor()(pil_img)

def load_images(source, data_dir, num_samples):
    """Load images from the specified source. Returns list of [3,H,W] tensors."""
    if source == "stl10":
        return _load_stl10(os.path.join(data_dir, "stl10"))
    elif source == "imagenette":
        return _load_imagenette(data_dir)
    elif source == "caltech101":
        return _load_caltech101(data_dir)
    elif source == "caltech256":
        return _load_caltech256(data_dir)
    elif source == "imagenet":
        return _load_imagenet(data_dir, num_samples)
    else:
        raise ValueError(f"Unknown source: {source}. Choose from: {list(SOURCES)}")

def idx_to_char(idx: int) -> str:
    if idx == PAD_TOKEN:
        return " "
    if idx == MASK_TOKEN:
        return "?"
    return _idx_to_char[idx]

def grid_to_string(int_grid: torch.Tensor) -> str:
    """Convert a [H, W] int tensor to a multi-line ASCII string."""
    lines = []
    for row in int_grid:
        lines.append("".join(idx_to_char(idx.item()) for idx in row))
    return "\n".join(lines)

def string_to_grid(text: str) -> torch.Tensor:
    """Convert a multi-line ASCII string to a [H, W] int tensor."""
    lines = text.split("\n")
    h = len(lines)
    w = max(len(line) for line in lines) if lines else 0
    grid = torch.full((h, w), char_to_idx(" "), dtype=torch.long)
    for r, line in enumerate(lines):
        for c, ch in enumerate(line):
            if ch in _char_to_idx:
                grid[r, c] = _char_to_idx[ch]
    return grid

def _set(grid, r, c, ch_idx):
    if 0 <= r < GRID_H and 0 <= c < GRID_W:
        grid[r, c] = ch_idx

def draw_diagonal(grid):
    direction = random.choice(["/", "\\"])
    ch = char_to_idx(direction)
    r0 = random.randint(2, GRID_H - 3)
    c0 = random.randint(2, GRID_W - 3)
    length = random.randint(3, 15)
    for i in range(length):
        if direction == "\\":
            _set(grid, r0 + i, c0 + i, ch)
        else:
            _set(grid, r0 - i, c0 + i, ch)

